def fail(message):
    print('STOP: ' + message, file=sys.stderr)
    sys.exit(1)


def digest(data):
    return hashlib.sha256(data).hexdigest()


if len(sys.argv) == 1:
    sys.argv.append('--apply')
if len(sys.argv) != 2 or sys.argv[1] not in ['--check', '--apply', '--verify']:
    fail('Use no argument (apply), --check, --apply or --verify from the repository root.')
mode = sys.argv[1]
try:
    root = pathlib.Path(subprocess.check_output(
        ['git', 'rev-parse', '--show-toplevel'], stderr=subprocess.DEVNULL
    ).decode().strip()).resolve()
except Exception:
    fail('Not inside a Git repository.')
if pathlib.Path.cwd().resolve() != root:
    fail('Run from your existing repository root; no files changed.')
pubspec = root / 'pubspec.yaml'
if not pubspec.is_file() or 'name: maxplayer' not in pubspec.read_text():
    fail('This is not the MaxPlayer / Vaxlo Player Android repository.')
blob = base64.b64decode(PAYLOAD)
if digest(blob) != PAYLOAD_HASH:
    fail('Payload checksum mismatch.')
entries = json.loads(gzip.decompress(blob))


def inspect(rel):
    path = root / rel
    pure = pathlib.PurePosixPath(rel)
    if pure.is_absolute() or '..' in pure.parts:
        fail('Unsafe payload path.')
    for part in [path, *path.parents]:
        if part == root:
            break
        if part.is_symlink():
            fail('Symlink not allowed: ' + rel)
    if path.exists() and not path.is_file():
        fail('Not a file: ' + rel)
    return path.read_bytes() if path.exists() else None


def hash_or_none(data):
    return None if data is None else digest(data)


changes = []
originals = {}
for e in entries:
    rel = e['path']
    if rel.startswith(('desktop/', 'admin/', '.github/')):
        fail('Unexpected scope: ' + rel)
    data = None if e['data'] is None else base64.b64decode(e['data'])
    if hash_or_none(data) != e['after']:
        fail('Invalid embedded file: ' + rel)
    current = inspect(rel)
    h = hash_or_none(current)
    if h == e['after']:
        continue
    if mode == '--verify':
        fail('Installed file differs: ' + rel)
    if h != e['before']:
        fail('Unrecognized local edits/baseline: ' + rel +
             '. Nothing changed. Keep your work; do not force overwrite.')
    changes.append((rel, data))
    originals[rel] = current
if mode == '--verify':
    print('VERIFIED: all ' + str(len(entries)) + ' payload hashes match.')
    sys.exit(0)
print('Android-only payload (RunX Player rename (with Instagram + Telegram links)): ' + str(len(entries)) +
      ' files; ' + str(len(changes)) + ' need updates. ' +
      'Package id, signing, desktop/, admin/ and workflows unchanged.')
if mode == '--check':
    print('CHECK PASSED. No files written.')
    sys.exit(0)
if not changes:
    print('Already applied; no files changed.')
    sys.exit(0)
backup = pathlib.Path(subprocess.check_output(
    ['git', 'rev-parse', '--git-path', 'runx87-backups']).decode().strip())
if not backup.is_absolute():
    backup = root / backup
backup = backup / datetime.datetime.now(datetime.timezone.utc).strftime(
    '%Y%m%dT%H%M%S.%fZ')
backup.mkdir(parents=True, exist_ok=False)
for rel, data in originals.items():
    if data is not None:
        dest = backup / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(data)
(backup / 'manifest.json').write_text(json.dumps(
    [{'path': r, 'existed': d is not None} for r, d in originals.items()],
    indent=2))


def replace(rel, data):
    p = root / rel
    if data is None:
        p.unlink(missing_ok=True)
        return
    p.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(dir=p.parent, delete=False) as tmp:
        temp = pathlib.Path(tmp.name)
        tmp.write(data)
    os.chmod(temp, 0o644)
    os.replace(temp, p)


written = []
try:
    for rel, data in changes:
        if inspect(rel) != originals[rel]:
            raise RuntimeError('File changed during apply: ' + rel)
        replace(rel, data)
        written.append(rel)
    for e in entries:
        if hash_or_none(inspect(e['path'])) != e['after']:
            raise RuntimeError('Post-apply verification: ' + e['path'])
except BaseException:
    for rel in reversed(written):
        replace(rel, originals[rel])
    raise
print('APPLIED and hash-verified. Backup: ' + str(backup))
print('Version is now 1.0.1+87. No build, dependency install, Git commit/push ' +
      'or Play Console change performed.')
print('Next: flutter pub get; flutter analyze; flutter test; build APK/AAB via ' +
      'your GitHub Actions workflow.')
ANDROID87_PY
